#include <metal_stdlib>
using namespace metal;

// A continuous autumn shower of chestnut burrs and a few bare nuts.
struct ShaderUniforms {
    float4 resolutionTime; // width, height, seconds, unused
    float4 mouse;          // reserved by the shader-state contract
};

float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}

float noise2(float2 p) {
    float2 cell = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash21(cell), hash21(cell + float2(1.0, 0.0)), f.x),
               mix(hash21(cell + float2(0.0, 1.0)),
                   hash21(cell + float2(1.0, 1.0)), f.x), f.y);
}

float3 burrColor(float2 p, float radius, float angle, float seed) {
    float grain = noise2(p * 18.0 + seed * 31.0);
    float light = clamp(0.70 + 0.21 * (p.y - p.x) + 0.15 * (1.0 - radius),
                        0.35, 1.16);
    float3 green = mix(float3(0.31, 0.39, 0.15),
                       float3(0.51, 0.42, 0.20), seed);
    float3 color = green * light * (0.85 + 0.27 * grain);

    // Pale spines radiate from the husk; their roots remain darker green.
    float spine = pow(0.5 + 0.5 * cos(angle * 36.0 + 0.7 * sin(angle * 7.0)),
                      10.0);
    float tips = smoothstep(0.61, 0.90, radius);
    color = mix(color, float3(0.77, 0.67, 0.35) * light,
                spine * tips * 0.83);

    // A narrow split in some burrs reveals the deep brown inner shell.
    if (seed > 0.48) {
        float2 opening = float2(0.90 * p.x + 0.43 * p.y,
                                -0.43 * p.x + 0.90 * p.y);
        float cut = length(opening / float2(0.19, 0.56));
        float aperture = 1.0 - smoothstep(0.85, 1.08, cut);
        color = mix(color, float3(0.19, 0.105, 0.055), aperture * 0.87);
        float inner = length((opening - float2(0.045, -0.05))
                             / float2(0.11, 0.39));
        color = mix(color, float3(0.43, 0.20, 0.085),
                    (1.0 - smoothstep(0.78, 1.0, inner)) * aperture);
    }
    return color;
}

float3 nutColor(float2 p, float radius, float seed) {
    float grain = noise2(p * 12.0 + seed * 41.0);
    float light = clamp(0.49 + 0.32 * (p.y - p.x) + 0.24 * (1.0 - radius),
                        0.30, 1.12);
    float3 color = float3(0.43, 0.16, 0.075) * light
                   * (0.90 + 0.18 * grain);
    float highlight = exp(-dot((p - float2(-0.29, 0.27))
                                / float2(0.19, 0.32),
                                (p - float2(-0.29, 0.27))
                                / float2(0.19, 0.32)) * 1.5);
    color += float3(0.33, 0.17, 0.095) * highlight;

    // The broad cream scar is characteristic of a shelled chestnut.
    float scar = (1.0 - smoothstep(-0.50, -0.35, p.y))
                 * (1.0 - smoothstep(0.42, 0.73, abs(p.x)));
    color = mix(color, float3(0.78, 0.59, 0.35)
                       * (0.87 + 0.16 * grain), scar);
    return color;
}

float3 renderChestnutRain(float2 screen, float2 resolution, float time) {
    float aspect = resolution.x / resolution.y;
    float sky = smoothstep(-1.2, 1.2, screen.y);
    float3 color = mix(float3(0.87, 0.82, 0.69),
                       float3(0.62, 0.72, 0.70), sky);
    color += (noise2(screen * 85.0) - 0.5) * 0.012;

    // Draw small distant pieces first, then the larger foreground pieces.
    // Four of the 32 pieces are bare chestnuts; the rest wear spiky husks.
    for (int i = 0; i < 32; ++i) {
        float index = float(i);
        float seed = hash21(float2(index, 19.7));
        float size = 0.092 + 0.080 * index / 31.0
                     + 0.019 * hash21(float2(index, 8.3));
        float speed = 0.16 + 0.095 * hash21(float2(index, 5.1));
        float phase = fract((index + 0.5) / 32.0 + time * speed);
        float2 center = float2(
            (2.0 * hash21(float2(index, 13.4)) - 1.0) * (aspect - 0.03)
                + 0.10 * sin(time * (0.8 + seed) + index * 2.3),
            1.30 - 2.60 * phase);
        float2 delta = screen - center;
        if (abs(delta.x) > size * 1.20 || abs(delta.y) > size * 1.20)
            continue;

        float rotation = time * (1.0 + seed * 1.1) + index * 2.4;
        float c = cos(rotation), s = sin(rotation);
        float2 p = float2(c * delta.x + s * delta.y,
                          -s * delta.x + c * delta.y) / size;
        float radius = length(p);
        if (radius > 1.20) continue;

        bool bare = (i % 8 == 1);
        float edge;
        float3 piece;
        if (bare) {
            // A rounded, pointed nut with a pale base and a lacquered sheen.
            float width = 0.79 - 0.25 * max(p.y, 0.0);
            edge = length(float2(p.x / width, p.y / 0.87)) - 1.0;
            piece = nutColor(p, radius, seed);
        } else {
            // Irregular radial spines turn each husk into a chestnut burr.
            float angle = atan2(p.y, p.x);
            float spine = pow(0.5 + 0.5
                              * cos(angle * 36.0 + 0.7 * sin(angle * 7.0)),
                              10.0);
            float outline = 0.72 + 0.29 * spine
                            + 0.035 * sin(angle * 11.0 + seed * 9.0);
            edge = radius - outline;
            piece = burrColor(p, radius, angle, seed);
        }
        float aa = max(2.0 / (resolution.y * size), 0.008);
        float coverage = 1.0 - smoothstep(-aa, aa, edge);
        color = mix(color, piece, coverage);
    }
    return clamp(color, float3(0.0), float3(1.0));
}

vertex float4 fullscreenVertex(uint vertexID [[vertex_id]]) {
    float2 p = float2((vertexID << 1) & 2, vertexID & 2);
    return float4(p * 2.0 - 1.0, 0.0, 1.0);
}

fragment float4 chestnutRainFragment(
    float4 position [[position]], constant ShaderUniforms &uniforms [[buffer(0)]]) {
    float2 resolution = uniforms.resolutionTime.xy;
    float2 frag = float2(position.x, resolution.y - position.y);
    float2 screen = (frag - 0.5 * resolution) * (2.0 / resolution.y);
    return float4(renderChestnutRain(screen, resolution,
                                     uniforms.resolutionTime.z), 1.0);
}
